begin;
create table trade_business.signatures(company_id uuid not null,id uuid not null,file_id uuid not null,name text not null,enabled boolean not null default true,version integer not null default 1 check(version>0),created_by uuid not null,primary key(company_id,id),unique(company_id,file_id),foreign key(company_id,file_id) references trade_business.file_assets(company_id,id));
create table trade_business.signature_grants(company_id uuid not null,signature_id uuid not null,user_id uuid not null,purpose text not null check(purpose in ('PI','PO','CI','PL','SC')),enabled boolean not null,version integer not null default 1 check(version>0),primary key(company_id,signature_id,user_id,purpose),foreign key(company_id,signature_id) references trade_business.signatures(company_id,id));
create table trade_business.signature_usages(company_id uuid not null,id uuid not null,signature_id uuid not null,document_id uuid not null,expected_document_version integer not null,document_version_id uuid,actor_id uuid not null,grant_version integer not null,file_id uuid not null,file_hash text not null check(file_hash ~ '^[a-f0-9]{64}$'),state text not null default 'prepared' check(state in ('prepared','used')),primary key(company_id,id),unique(company_id,document_version_id),foreign key(company_id,signature_id) references trade_business.signatures(company_id,id),foreign key(company_id,document_id) references trade_business.documents(company_id,id),foreign key(company_id,document_version_id) references trade_business.document_versions(company_id,id),foreign key(company_id,file_id) references trade_business.file_assets(company_id,id));
alter table trade_business.document_versions add foreign key(company_id,signature_usage_id) references trade_business.signature_usages(company_id,id);
grant select,insert on trade_business.signatures,trade_business.signature_grants,trade_business.signature_usages to business_backend;
grant update(enabled,version) on trade_business.signatures,trade_business.signature_grants to business_backend;
grant update(document_version_id,state) on trade_business.signature_usages to business_backend;
commit;
